import { useState, useMemo } from "react";
import { View, Text, TextInput, Pressable, FlatList } from "react-native";

export default function App() {
  const [todos, setTodos] = useState([{ id: 1, title: "Học React Native", done: false }]);
  const [text, setText] = useState("");
  const [filter, setFilter] = useState("all");          // all | active | done

  const add = () => {
    const title = text.trim();
    if (!title) return;
    setTodos((prev) => [...prev, { id: Date.now(), title, done: false }]);
    setText("");
  };
  const toggle = (id) => setTodos((prev) => prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  const remove = (id) => setTodos((prev) => prev.filter((t) => t.id !== id));

  const visible = useMemo(
    () => todos.filter((t) => (filter === "all" ? true : filter === "done" ? t.done : !t.done)),
    [todos, filter]
  );
  const left = todos.filter((t) => !t.done).length;      // DẪN XUẤT, không lưu riêng

  return (
    <View>
      <TextInput testID="input" value={text} onChangeText={setText} placeholder="Việc cần làm" onSubmitEditing={add} />
      <Pressable testID="add" accessibilityRole="button" onPress={add}><Text>Thêm</Text></Pressable>
      <Text testID="left">{left}</Text>
      <Pressable testID="f-done" onPress={() => setFilter("done")}><Text>Đã xong</Text></Pressable>
      <FlatList
        data={visible}
        keyExtractor={(t) => String(t.id)}
        ListEmptyComponent={<Text testID="empty">Không có việc nào</Text>}
        renderItem={({ item }) => (
          <View>
            <Pressable testID="todo" onPress={() => toggle(item.id)}><Text>{item.done ? "✓ " : ""}{item.title}</Text></Pressable>
            <Pressable testID="del" onPress={() => remove(item.id)}><Text>Xoá</Text></Pressable>
          </View>
        )}
      />
    </View>
  );
}

